export declare const basicCaptionsElementSource = "import type {Caption} from '@remotion/captions';\nimport {createTikTokStyleCaptions} from '@remotion/captions';\nimport React, {forwardRef, useImperativeHandle, useMemo, useRef} from 'react';\nimport {\n\tInteractive,\n\tSequence,\n\tuseCurrentFrame,\n\tuseVideoConfig,\n\ttype InteractiveBaseProps,\n\ttype InteractiveTransformProps,\n\ttype InteractivitySchema,\n\ttype SequenceControls,\n\ttype SequenceProps,\n} from 'remotion';\n\ntype BasicCaptionsProps = InteractiveBaseProps &\n\tInteractiveTransformProps &\n\tPick<SequenceProps, 'from' | 'durationInFrames' | 'trimBefore' | 'width' | 'height'> & {\n\t\treadonly captions: Caption[];\n\t\treadonly playbackRate?: number;\n\t\treadonly combineTokensWithinMilliseconds?: number;\n\t};\n\nconst BasicCaptionsContent: React.FC<{\n\treadonly captions: Caption[];\n\treadonly playbackRate: number;\n\treadonly trimBefore: number;\n\treadonly combineTokensWithinMilliseconds: number;\n}> = ({captions, playbackRate, trimBefore, combineTokensWithinMilliseconds}) => {\n\tconst frame = useCurrentFrame();\n\tconst {fps} = useVideoConfig();\n\tconst pages = useMemo(\n\t\t() =>\n\t\t\tcreateTikTokStyleCaptions({\n\t\t\t\tcaptions,\n\t\t\t\tcombineTokensWithinMilliseconds,\n\t\t\t}).pages,\n\t\t[captions, combineTokensWithinMilliseconds],\n\t);\n\t// The Sequence frame already includes trimBefore; only elapsed frames speed up.\n\tconst currentTimeMs =\n\t\t((trimBefore + (frame - trimBefore) * playbackRate) / fps) * 1000;\n\tconst page = pages.find(\n\t\t(candidate) =>\n\t\t\tcurrentTimeMs >= candidate.startMs &&\n\t\t\tcurrentTimeMs < candidate.startMs + candidate.durationMs,\n\t);\n\n\tif (!page) {\n\t\treturn null;\n\t}\n\n\treturn (\n\t\t<div\n\t\t\tstyle={{\n\t\t\t\tbackgroundColor: 'rgba(64, 64, 64, 0.75)',\n\t\t\t\tcolor: '#ffffff',\n\t\t\t\tdisplay: '-webkit-box',\n\t\t\t\tfontFamily: 'Arial, Helvetica, sans-serif',\n\t\t\t\tfontSize: 64,\n\t\t\t\tfontWeight: 400,\n\t\t\t\tlineHeight: 1.2,\n\t\t\t\toverflow: 'hidden',\n\t\t\t\tpadding: '14px 22px',\n\t\t\t\ttextAlign: 'center',\n\t\t\t\ttextWrap: 'balance',\n\t\t\t\tWebkitBoxOrient: 'vertical',\n\t\t\t\tWebkitLineClamp: 2,\n\t\t\t\twhiteSpace: 'pre-wrap',\n\t\t\t}}\n\t\t>\n\t\t\t{page.text.trim()}\n\t\t</div>\n\t);\n};\n\nconst basicCaptionsSchema = {\n\t...Interactive.baseSchema,\n\t...Interactive.captionsSchema,\n\twidth: {\n\t\ttype: 'number',\n\t\tmin: 1,\n\t\tstep: 1,\n\t\tdefault: undefined,\n\t\tdescription: 'Caption area width',\n\t\thiddenFromList: false,\n\t},\n\theight: {\n\t\ttype: 'number',\n\t\tmin: 1,\n\t\tstep: 1,\n\t\tdefault: undefined,\n\t\tdescription: 'Caption area height',\n\t\thiddenFromList: false,\n\t},\n\tcombineTokensWithinMilliseconds: {\n\t\ttype: 'number',\n\t\tmin: 0,\n\t\tstep: 50,\n\t\tdefault: 2000,\n\t\tdescription: 'Time between caption pages',\n\t\thiddenFromList: false,\n\t},\n\t...Interactive.transformSchema,\n} as const satisfies InteractivitySchema;\n\nconst BasicCaptionsInner = forwardRef<\n\tHTMLDivElement,\n\tBasicCaptionsProps & {readonly controls: SequenceControls | undefined}\n>(\n\t(\n\t\t{\n\t\t\tcaptions,\n\t\t\tcombineTokensWithinMilliseconds = 2000,\n\t\t\tcontrols,\n\t\t\tdurationInFrames,\n\t\t\tfrom,\n\t\t\theight = 220,\n\t\t\tname,\n\t\t\tplaybackRate = 1,\n\t\t\tstyle,\n\t\t\ttrimBefore,\n\t\t\twidth = 900,\n\t\t\t...interactiveProps\n\t\t},\n\t\tref,\n\t) => {\n\t\tconst outlineRef = useRef<HTMLDivElement>(null);\n\t\tuseImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);\n\n\t\treturn (\n\t\t\t<Sequence\n\t\t\t\tlayout=\"none\"\n\t\t\t\t{...interactiveProps}\n\t\t\t\tcontrols={controls}\n\t\t\t\tname={name ?? 'Basic captions'}\n\t\t\t\tfrom={from}\n\t\t\t\tdurationInFrames={durationInFrames}\n\t\t\t\ttrimBefore={trimBefore}\n\t\t\t\toutlineRef={outlineRef}\n\t\t\t>\n\t\t\t\t<div\n\t\t\t\t\tref={outlineRef}\n\t\t\t\t\tstyle={{\n\t\t\t\t\t\talignItems: 'center',\n\t\t\t\t\t\tdisplay: 'flex',\n\t\t\t\t\t\tjustifyContent: 'center',\n\t\t\t\t\t\tposition: 'absolute',\n\t\t\t\t\t\tbottom: 120,\n\t\t\t\t\t\tleft: '50%',\n\t\t\t\t\t\ttransform: 'translateX(-50%)',\n\t\t\t\t\t\twidth,\n\t\t\t\t\t\theight,\n\t\t\t\t\t\t...style,\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t<BasicCaptionsContent\n\t\t\t\t\t\tcaptions={captions}\n\t\t\t\t\t\tcombineTokensWithinMilliseconds={combineTokensWithinMilliseconds}\n\t\t\t\t\t\tplaybackRate={playbackRate}\n\t\t\t\t\t\ttrimBefore={trimBefore ?? 0}\n\t\t\t\t\t/>\n\t\t\t\t</div>\n\t\t\t</Sequence>\n\t\t);\n\t},\n);\n\nexport const BasicCaptions = Interactive.withSchema({\n\tComponent: BasicCaptionsInner,\n\tcomponentName: '<BasicCaptions>',\n\tschema: basicCaptionsSchema,\n\tsupportsEffects: false,\n}) as React.FC<BasicCaptionsProps>;\n";
